observations.source:
rules_version = '2';
service cloud.firestore {
  match /databases/{database}/documents {
    match /phase3/{document} {
      allow get: if ;
    }
  }
}

rules_version = '2';
service cloud.firestore {
  match /databases/{database}/documents {
    match /phase3/{document} {
      function duplicate() { let value = 1; let value = 2; return value == 2; }
      allow get: if duplicate();
    }
  }
}

rules_version = '2';
service cloud.firestore {
  match /databases/{database}/documents {
    match /phase3/{document} {
      allow get: if missingName == 1;
    }
  }
}

rules_version = '2';
service cloud.firestore {
  match /databases/{database}/documents {
    match /phase3/{document} {
      allow get: if math.abs() == 1;
    }
  }
}

rules_version = '2';
service cloud.firestore {
  match /databases/{database}/documents {
    match /phase3/{document} {
      function recurse() { return recurse(); }
      allow get: if recurse();
    }
  }
}

rules_version = '2';
service cloud.firestore {
  match /databases/{database}/documents {
    match /{first=**}/{second=**} {
      allow get: if true;
    }
  }
}

rules_version = '2';
service cloud.firestore {
  match /databases/{database}/documents {
    match /phase3/{document} {
      allow get: if true;
    }
  }
}
